// Prism Satchel + Warden Trials parity: DaedalusPrismSatchelCore.h must reproduce every payout, seal, spend and save in
// prism_satchel_parity.txt (generated by tools/minigames/prism_satchel_parity.py) from the inputs alone.
//   g++ -std=c++17 -O1 -Wall -Wextra -Wshadow -Werror -I../DaedalusLink/Source/DaedalusLink/Public prism_satchel_core_test.cpp -o prism_satchel_core_test && ./prism_satchel_core_test prism_satchel_parity.txt
#include "DaedalusPrismSatchelCore.h"
#include <cstdio>
#include <fstream>
#include <string>

using namespace daedalus::prism_satchel;

namespace {

std::string Field(const std::string& Line, const std::string& Key)
{
	const std::string Needle = " " + Key + "=";
	const size_t P = Line.find(Needle);
	if (P == std::string::npos) return "";
	const size_t S = P + Needle.size(), E = Line.find(' ', S);
	return Line.substr(S, E == std::string::npos ? std::string::npos : E - S);
}

int Fails = 0;

void Expect(bool Ok, int LineNo, const std::string& What)
{
	if (!Ok && ++Fails <= 20) std::printf("line %d: %s\n", LineNo, What.c_str());
}

}  // namespace

int main(int Argc, char** Argv)
{
	if (Argc < 2)
	{
		std::printf("usage: prism_satchel_core_test prism_satchel_parity.txt\n");
		return 2;
	}
	std::ifstream In(Argv[1]);
	if (!In)
	{
		std::printf("cannot open %s\n", Argv[1]);
		return 2;
	}
	Satchel S;
	std::string Line;
	int No = 0, Results = 0, Spends = 0, Loads = 0, Pays = 0;
	while (std::getline(In, Line))
	{
		++No;
		if (Line.rfind("pays ", 0) == 0)
		{
			const Payout* P = FindPayout(Field(Line, "g"));
			Expect(P != nullptr, No, "unknown game in payout table");
			if (!P) continue;
			const std::string Heart = P->HeartPar < 0 ? "perfect" : std::to_string(P->HeartPar);
			Expect(Field(Line, "hue") == Hues[P->Hue] && Field(Line, "div") == std::to_string(P->Divisor) && Field(Line, "umbra") == std::to_string(P->UmbraPar)
					   && Field(Line, "heart") == Heart,
				No, "payout table differs for " + Field(Line, "g"));
			++Pays;
		}
		else if (Line.rfind("result ", 0) == 0)
		{
			const RecordResult R = S.Record(Field(Line, "g"), Field(Line, "d"), std::stoll(Field(Line, "score")), Field(Line, "won") == "1", Field(Line, "perfect") == "1");
			Expect(R.Ok, No, "record refused");
			Expect(std::to_string(R.Pay) == Field(Line, "pay"), No, "pay " + std::to_string(R.Pay) + " != " + Field(Line, "pay"));
			Expect(Hues[R.Hue] == Field(Line, "hue"), No, "hue differs");
			Expect(std::to_string(R.Seal) == Field(Line, "seal") && std::to_string(R.Gained) == Field(Line, "new"), No, "seal differs");
			Expect(S.ToText() == Field(Line, "text"), No, "satchel " + S.ToText());
			++Results;
		}
		else if (Line.rfind("spend ", 0) == 0)
		{
			std::array<long long, HueCount> Cost{};
			std::string C = Field(Line, "cost") + ",";
			for (size_t At = 0, Comma; (Comma = C.find(',', At)) != std::string::npos; At = Comma + 1)
			{
				const std::string Item = C.substr(At, Comma - At);
				const size_t Colon = Item.find(':');
				const int H = HueIndex(Item.substr(0, Colon));
				Expect(H >= 0, No, "bad hue in cost");
				if (H >= 0) Cost[H] = std::stoll(Item.substr(Colon + 1));
			}
			const bool Ok = S.Spend(Cost);
			Expect((Ok ? "1" : "0") == Field(Line, "ok"), No, "spend ok differs");
			Expect(S.ToText() == Field(Line, "text"), No, "satchel after spend " + S.ToText());
			++Spends;
		}
		else if (Line.rfind("start ", 0) == 0)
		{
			const std::optional<Satchel> L = Satchel::FromText(Field(Line, "text"));
			Expect(L.has_value(), No, "start save refused");
			if (L) S = *L;
		}
		else if (Line.rfind("mastery ", 0) == 0)
		{
			Expect(std::to_string(S.Mastered()) == Field(Line, "mastered") && std::to_string(S.Heartglass()) == Field(Line, "heartglass"), No, "mastery counts differ");
		}
		else if (Line.rfind("load ", 0) == 0)
		{
			const std::string Text = Field(Line, "text");
			const std::optional<Satchel> L = Satchel::FromText(Text);
			Expect((L ? "1" : "0") == Field(Line, "ok"), No, "load ok differs for " + Text);
			if (L) Expect(L->ToText() == Text, No, "round trip differs");
			++Loads;
		}
	}
	// Direct checks the fixture does not cover.
	Satchel E;
	Expect(!E.Spend({}), 0, "empty cost must be refused");
	Expect(!E.Spend({-1, 0, 0, 0, 0}), 0, "negative cost must be refused");
	Expect(!E.Record("nogame", "hard", 1, true, false).Ok && !E.Record("glowmoss", "brutal", 1, true, false).Ok, 0, "unknown game/difficulty must be refused");
	Expect(!E.Record("glowmoss", "hard", -1, true, false).Ok && !E.Record("glowmoss", "hard", 1, false, true).Ok, 0, "bad score/perfect must be refused");
	Expect(!Satchel::FromText(std::string(SaveMax + 1, '1')) && !Satchel::FromText("") && E.Runs == 0, 0, "oversized/empty save must be refused");
	Expect(Pays == 11 && Results > 0 && Spends > 0 && Loads > 0, 0, "fixture is missing sections");
	std::printf("prism satchel parity: %d payouts, %d results, %d spends, %d loads, %d failures\n", Pays, Results, Spends, Loads, Fails);
	return Fails ? 1 : 0;
}
